import os import shutil from datetime import datetime from pathlib import Path
def organize_by_date(source_dir, target_dir, date_source='modified'): """Organize files into YYYY-MM folders by date""" source = Path(source_dir) target = Path(target_dir)
for file_path in source.rglob('*'): if file_path.is_file(): if date_source == 'modified': file_date = datetime.fromtimestamp(file_path.stat().st_mtime) elif date_source == 'created': file_date = datetime.fromtimestamp(file_path.stat().st_ctime)
date_folder = file_date.strftime('%Y-%m') target_folder = target / date_folder target_folder.mkdir(parents=True, exist_ok=True)
shutil.move(str(file_path), str(target_folder / file_path.name))

import os
from pathlib import Path
try:
    from PyPDF2 import PdfReader
except ImportError:
    PdfReader = None

def extract_pdf_metadata(file_path):
    """Extract metadata from PDF files"""
    if not PdfReader:
        return {}

    try:
        reader = PdfReader(file_path)
        info = reader.metadata
        return {
            'title': info.title or '',
            'author': info.author or '',
            'subject': info.subject or '',
            'creator': info.creator or ''
        }
    except:
        return {}

def rename_by_metadata(directory):
    """Rename PDF files based on their metadata"""
    path = Path(directory)
    for pdf_file in path.glob('*.pdf'):
        metadata = extract_pdf_metadata(pdf_file)
        if metadata.get('title') and metadata.get('author'):
            title = metadata['title'].replace(' ', '_').replace('/', '-')
            author = metadata['author'].replace(' ', '_').replace('/', '-')
            new_name = f"{author}_{title}.pdf"
            new_path = pdf_file.parent / new_name
            pdf_file.rename(new_path)
